<template><AppShell><header class="page-head"><span class="eyebrow"><WandSparkles :size="15" />AGENT GENERATION</span><h1>生成学习资源</h1><p>智能体将结合当前画像、主题与附件生成结构化结果。</p></header><div class="notice-band"><ShieldCheck :size="18" /><span>生成内容会经过知识依据、结构校验和质量审核；不确定内容应显示核验标记。</span></div>
  <form class="form-stack resource-form" @submit.prevent="submit"><div class="field"><span>资源类型</span><div class="choice-grid"><button v-for="item in types" :key="item.value" type="button" :class="{active:form.resourceType===item.value}" @click="form.resourceType=item.value"><component :is="item.icon" :size="19" />{{ item.label }}</button></div></div><label class="field"><span>学习主题</span><input v-model.trim="form.topic" required maxlength="160" placeholder="例如：STM32 定时器与 PWM" /></label><label class="field"><span>补充要求</span><textarea v-model.trim="form.prompt" placeholder="难度、重点、呈现方式等"></textarea></label><label class="field"><span>补充材料（可选）</span><input type="file" multiple accept="image/*,.pdf,.doc,.docx,.txt,.ppt,.pptx" @change="selectFiles" /><small v-if="files.length">已选择 {{ files.length }} 个文件</small></label><template v-if="form.resourceType==='generated_video'"><label class="field"><span>视频清晰度</span><select v-model="form.resolution"><option value="480p">480p</option><option value="720p">720p</option><option value="1080p">1080p</option></select></label><div class="notice-band"><CircleAlert :size="18" /><span>AI 视频会先保存提示词，需在任务详情页再次确认后才会调用媒体模型。</span></div></template><p v-if="error" class="form-error">{{ error }}</p><button class="primary-btn full-btn" :disabled="submitting"><span v-if="submitting" class="spinner light"></span><WandSparkles v-else :size="18" />{{ submitting?'正在创建任务':'创建后台生成任务' }}</button></form></AppShell></template>
<script setup>
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { BookOpenCheck,CircleAlert,Clapperboard,FileText,Network,Presentation,ShieldCheck,Video,WandSparkles } from 'lucide-vue-next';import AppShell from '../components/AppShell.vue';import { createResourceTask,uploadInputs } from '../services/api.js';import { trackTask } from '../stores/tasks.js'
const router=useRouter(),submitting=ref(false),error=ref(''),files=ref([]);const form=reactive({resourceType:'question_bank',topic:'',prompt:'',resolution:'720p'});const types=[{value:'question_bank',label:'题库',icon:BookOpenCheck},{value:'document',label:'文档',icon:FileText},{value:'ppt',label:'PPT',icon:Presentation},{value:'mindmap',label:'导图',icon:Network},{value:'video',label:'视频检索',icon:Video},{value:'generated_video',label:'AI 视频',icon:Clapperboard},{value:'animation',label:'教学动画',icon:WandSparkles}]
function selectFiles(e){files.value=[...e.target.files].slice(0,8)}async function submit(){submitting.value=true;error.value='';try{const uploaded=files.value.length?await uploadInputs(files.value,'resource'):[];const response=await createResourceTask({resourceType:form.resourceType,topic:form.topic,prompt:form.prompt||form.topic,params:{attachmentIds:uploaded.map(x=>x.id),resolution:form.resolution}});const task=response?.data?.task||response?.data?.tasks?.[0]||response?.task;if(!task?.taskId)throw new Error('后端未返回任务编号');trackTask(task);await router.replace(`/resources/task/${task.taskId}`)}catch(e){error.value=e.message}finally{submitting.value=false}}
</script>
<style scoped>.resource-form{margin-top:16px;padding:17px;border:1px solid #dce5e0;border-radius:7px;background:white}.choice-grid button{min-height:66px;flex-direction:column;gap:6px;border-radius:6px}.choice-grid button.active{border-color:#176f4b;background:#edf5f1;box-shadow:inset 0 0 0 1px #176f4b}.field input[type=file]{min-height:74px;padding:12px;border:1px dashed #9eb8aa;border-radius:6px;background:#f5f9f7;color:#52665c}.field input[type=file]::file-selector-button{min-height:40px;margin-right:9px;padding:0 12px;border:0;border-radius:5px;background:#176f4b;color:white}.field>small{color:#66776e;font-size:10px}.form-error{margin:0;padding:10px;background:#fff0ec;color:#a04435;font-size:11px}.spinner.light{border-color:rgba(255,255,255,.45);border-top-color:white}@media (max-width:370px){.choice-grid{grid-template-columns:repeat(2,1fr)}}</style>
